      ],
      "rule": "weight+residual_pack+0.2*(residual_cover-residual_pack)-0.1*neighbor_pack-0.025*neighbor_cover+0.02*neighbor_edges/max(1e-9,abs(1+degree))-0.02*residual_edges/max(1e-9,abs(1+compatible_weight))",
      "rationale": "Favor feasible residual completion with modest optimism. Neighborhood packing and both edge counts supply distinctions beyond degree and neighborhood edge count alone."
    },
    {
      "name": "cover_priority",
      "features": [
        {
          "name": "neighbor_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "residual_edges",
