        },
        {
          "name": "residual_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "neighbor_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        },
        {
          "name": "neighbor_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        }
      ],
      "rule": "weight+0.75*residual_cover+0.25*residual_pack-0.15*neighbor_cover-0.05*neighbor_pack+0.025*neighbor_edges/max(1e-9,abs((1+degree)*(1+degree)))-0.025*residual_edges/max(1e-9,abs((1+compatible_weight)*(1+compatible_weight)))",
      "rationale": "Emphasize residual completion potential when a deterministic packing may be pessimistic. Independent neighborhood capacity estimates penalize displaced opportunities."
    },
    {
      "name": "density_switch",
      "features": [
        {
          "name": "neighbor_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "residual_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}]}
        },
        {
