        },
        {
          "name": "residual_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "neighbor_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        }
      ],
      "rule": "(weight+0.8*residual_cover+0.2*residual_pack if 2*active_edges>0.35*remaining_count*max(0,remaining_count-1) else weight+0.9*residual_pack+0.1*residual_cover)-0.1*neighbor_pack+0.02*neighbor_edges/max(1e-9,abs(1+degree))-0.02*residual_edges/max(1e-9,abs(1+compatible_weight))",
      "rationale": "Use packing mainly in sparse states and cover potential mainly in dense states. Active edge count supplies graph context for otherwise shared structural vectors."
    },
    {
      "name": "gap_blend",
      "features": [
        {
          "name": "neighbor_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
