        },
        {
          "name": "residual_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "neighbor_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        }
      ],
      "rule": "weight+residual_pack+(0.1+0.35*(station_gap+satellite_gap)/max(1e-9,abs(1+station_gap+satellite_gap)))*(residual_cover-residual_pack)-0.1*neighbor_cover+0.03*neighbor_edges/max(1e-9,abs(1+degree))-0.02*residual_edges/max(1e-9,abs(1+compatible_weight))-0.005*degree*(1+2*active_edges/max(1e-9,abs(remaining_count*max(1,remaining_count-1))))",
      "rationale": "Allow more residual optimism as temporal gaps tighten constraints. Residual edges distinguish equal local summaries, while active density scales the degree penalty."
    },
    {
      "name": "displacement_ratio",
      "features": [
        {
          "name": "neighbor_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
