        },
        {
          "name": "neighbor_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        },
        {
          "name": "neighbor_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        }
      ],
      "rule": "(weight+0.5*residual_pack)/max(1e-9,abs(1+0.5*neighbor_pack+0.5*neighbor_cover))+0.05*neighbor_edges/max(1e-9,abs((1+degree)*(1+degree)))-0.02*residual_edges/max(1e-9,abs(1+compatible_weight))-0.002*degree*active_edges/max(1e-9,abs(remaining_count*max(1,remaining_count-1)))",
      "rationale": "Rank completion reward relative to estimated independent reward displaced in the neighborhood. This tests a stronger opportunity-cost penalty than additive scoring."
    },
    {
      "name": "sparsity_capacity",
      "features": [
        {
          "name": "neighbor_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "residual_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}]}
        },
        {
          "name": "active_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "available", "args": []}]}]}
        },
        {
          "name": "residual_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "neighbor_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        }
      ],
      "rule": "weight+0.65*residual_pack+0.35*compatible_weight*compatible_weight/max(1e-9,abs(compatible_weight+2*residual_edges))-0.1*neighbor_pack+0.025*neighbor_edges/max(1e-9,abs(1+degree))-0.005*degree*active_edges/max(1e-9,abs(remaining_count*max(1,remaining_count-1)))",
      "rationale": "Blend residual packing with a density-based capacity proxy motivated by the unit-weight examples. Omitting clique partitions tests a cheaper structural interface."
    },
    {
      "name": "uncertainty_discount",
      "features": [
