        },
        {
          "name": "residual_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "neighbor_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        },
        {
          "name": "neighbor_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}
        }
      ],
      "rule": "weight+residual_pack+0.4*(residual_cover-residual_pack)/max(1e-9,abs(1+abs(neighbor_cover-neighbor_pack)))-0.125*neighbor_pack-0.025*neighbor_cover+0.02*neighbor_edges/max(1e-9,abs(1+degree))-0.02*residual_edges/max(1e-9,abs(1+compatible_weight))",
      "rationale": "Discount residual optimism when neighborhood packing and cover estimates disagree. Both residual and neighborhood summaries remain demanded structural witnesses."
    },
    {
      "name": "context_midpoint",
      "features": [
        {
          "name": "neighbor_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
