        },
        {
          "name": "residual_envelope",
          "expression": {
            "op": "add",
            "args": [
              {"op": "greedy_independent_weight", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]},
