            ]
          }
        }
      ],
      "rule": "weight+0.5*residual_envelope-0.15*neighbor_pack-0.05*neighbor_cover+(0.02+0.08*active_edges/max(1e-9,abs(remaining_count*max(1,remaining_count-1))))*neighbor_edges/max(1e-9,abs(1+degree))-0.02*residual_edges/max(1e-9,abs(1+compatible_weight))",
